    "recovery.cancel.btn": "སླར་གསོ་འདི་ཕྱིར་འཐེན་བྱས་ཏེ་དེའི་དུམ་བུ་རྣམས་བསྲེག",
    "recovery.cancel.done": "སླར་གསོ་ཕྱིར་འཐེན་བྱས་ཟིན། སྒྲིག་ཆས་འདིའི་ནང་བསྡུས་ཡོད་པའི་དུམ་བུ་རྣམས་བསྲེགས་ཟིན་པས། སྒུག་བཞིན་པའི་སླར་གསོ་དེ་ནམ་ཡང་མཇུག་སྒྲིལ་ཐབས་མེད། ནམ་ཞིག་སླར་ཡང་འགོ་འཛུགས་དགོས་བྱུང་ན། ཁྱེད་ཀྱི་རྒྱབ་སྐྱོར་བ་རྣམས་ལ་དུམ་བུའི་རྩིས་སྤྲོད་གསར་པ་ཞིག་ཞུ་རོགས།",
    "recovery.cancel.elapsedSuf": "ཡིན་ཞིང་། དེའི་རྩོད་ལན་དུས་ཡུན་ཡང་ཟིན་ཟིན་པ་རེད།",
    "recovery.cancel.none": "སྒྲིག་ཆས་འདིའི་སྟེང་སྒུག་བཞིན་པའི་སླར་གསོ་གང་ཡང་མི་གནས། བདག་གཉེར་གྱིས་ཐོ་གཞུང་གང་ཡང་མི་འཇོག་པས། རྒྱབ་སྐྱོར་བ་ཁོ་ནའི་སླར་གསོ་ཞིག་འདིར་ཕྱེ་ཡོད་ན་སྒྲིག་ཆས་འདིས་འཛིན་སྲིད་པའི་འདུན་པའི་ཡིག་ཆ་གཅིག་པུ་དེ་ལས་ཞིབ་བཤེར་མི་བྱེད།",
    "recovery.cancel.pendingPre": "རྒྱབ་སྐྱོར་བ་ཁོ་ནའི་སླར་གསོ་ཞིག་སྒྲིག་ཆས་འདིའི་བདག་གཉེར་རིམ་པའི་ནང་སྒུག་བཞིན་ཡོད། དེ་ཕྱེ་བའི་དུས་ནི་",
    "recovery.cancel.remainPre": "—",
    "recovery.cancel.remainSuf": "དེའི་རྩོད་ལན་དུས་ཡུན་ལས་ལྷག་ཡོད།",
    "recovery.cancel.title": "སྒུག་བཞིན་པའི་སླར་གསོ་ཞིག་ཕྱིར་འཐེན།",
    "recovery.cancel.warn": "སླར་གསོ་འདི་ཁྱེད་ཀྱིས་མ་བཙུགས་ན། ད་ལྟ་རང་ཕྱིར་འཐེན་བྱོས། ཕྱིར་འཐེན་གྱིས་དེ་མཚམས་འཇོག་ཅིང་། དེས་བསྡུས་པའི་རྒྱབ་སྐྱོར་བའི་དུམ་བུ་གཉིས་བསྲེག་པས། དེ་གཉིས་ནམ་ཡང་སྦྲེལ་ཐབས་མེད།",
    "recovery.done.cutBtn": "གསུམ་ལས་གཉིས་ཀྱི་ཚོགས་གསར་པ་ཞིག་བཟོ།",
